#pragma once
// TinyML gesture classifier for BandW: the C++ twin of tinyml/bandw_tinyml.py (features(), stream_events()).
// Needs a model header generated by that script (bandw_model.h). tinyml/parity_test.cpp checks that this file and
// the Python pipeline emit the same gestures on the same recording.
//
// Classes: 0 NONE, 1 WATER, 2 FOOD, 3 NO, 4 HELP. YES stays the IMU's hardware double tap.
#include <math.h>
#include <stdint.h>
#include "bandw_model.h"

class TinyGesture {
    static const int W = BANDW_MODEL_WINDOW, F = BANDW_MODEL_FEATURES, K = BANDW_MODEL_CLASSES;
    float roll[W], pitch[W], gx[W], gy[W], mag[W];
    int head = 0, count = 0, last = 0, agree = 0;
    uint32_t samples = 0, coolUntil = 0;
    float baseRoll = 0, basePitch = 0;

    static float deg(float r) { return r * 57.29577951f; }
    float at(const float* a, int i) const { return a[(head + i) % W]; }   // i = 0 oldest .. W-1 newest
public:
    float prob[K] = {};      // last inference, for the raw-data stream / debugging

    void calibrate(float x, float y, float z) {
        baseRoll = deg(atan2f(x, z));
        float m = sqrtf(x*x + y*y + z*z); if (m <= 0) m = 1;
        float s = y / m; basePitch = deg(asinf(s > 1 ? 1 : s < -1 ? -1 : s));
        head = count = last = agree = 0; samples = 0; coolUntil = 0;
    }

    void features(float* f) const {
        float rs = 0, rmin = 1e9f, rmax = -1e9f, over = 0, ps = 0, pmin = 1e9f, pmax = -1e9f;
        float gys = 0, gyMax = 0, gxs = 0, gxMax = 0, ms = 0, mMax = -1e9f, rStart = 0, rEnd = 0;
        int reversals = 0, lastStrong = 0;
        for (int i = 0; i < W; ++i) {
            float r = at(roll, i), p = at(pitch, i), a = at(gy, i), b = at(gx, i), m = at(mag, i);
            rs += r; if (r < rmin) rmin = r; if (r > rmax) rmax = r; if (fabsf(r) > 22) over += 1;
            if (i < 10) rStart += r; if (i >= W - 10) rEnd += r;
            ps += p; if (p < pmin) pmin = p; if (p > pmax) pmax = p;
            gys += a; if (fabsf(a) > gyMax) gyMax = fabsf(a);
            gxs += b; if (fabsf(b) > gxMax) gxMax = fabsf(b);
            ms += m; if (m > mMax) mMax = m;
            int strong = a > 60 ? 1 : a < -60 ? -1 : 0;
            if (strong) { if (lastStrong && strong != lastStrong) ++reversals; lastStrong = strong; }
        }
        float rm = rs / W, pm = ps / W, gym = gys / W, gxm = gxs / W, mm = ms / W;
        float pv = 0, gyv = 0, gxv = 0, mv = 0;
        for (int i = 0; i < W; ++i) {
            float d;
            d = at(pitch, i) - pm; pv += d * d;
            d = at(gy, i) - gym; gyv += d * d;
            d = at(gx, i) - gxm; gxv += d * d;
            d = at(mag, i) - mm; mv += d * d;
        }
        float v[F] = { rm, rmin, rmax, rEnd / 10 - rStart / 10, over / W,
                       pm, pmin, pmax, sqrtf(pv / W),
                       sqrtf(gyv / W), gyMax, (float)reversals,
                       sqrtf(gxv / W), gxMax, sqrtf(mv / W), mMax };
        for (int i = 0; i < F; ++i) f[i] = v[i];
    }

    void infer(const float* f) {
        float z[F], logit[K], mx = -1e30f, sum = 0;
        for (int i = 0; i < F; ++i) z[i] = (f[i] - BANDW_MU[i]) * BANDW_INV_SD[i];
        for (int k = 0; k < K; ++k) {
            float s = 0;
            for (int i = 0; i < F; ++i) s += z[i] * BANDW_W[i][k];
            logit[k] = s * BANDW_W_SCALE[k] + BANDW_B[k];
            if (logit[k] > mx) mx = logit[k];
        }
        for (int k = 0; k < K; ++k) { prob[k] = expf(logit[k] - mx); sum += prob[k]; }
        for (int k = 0; k < K; ++k) prob[k] /= sum;
    }

    // One IMU sample (g, deg/s) every 20 ms. Returns 0, or the class (1..4) the band should emit now.
    int update(float x, float y, float z, float gxDps, float gyDps) {
        float r = deg(atan2f(x, z)) - baseRoll;
        while (r > 180) r -= 360; while (r < -180) r += 360;
        float m = sqrtf(x*x + y*y + z*z), s = m > 0 ? y / m : 0;
        float p = deg(asinf(s > 1 ? 1 : s < -1 ? -1 : s)) - basePitch;
        roll[head] = r; pitch[head] = p; gx[head] = gxDps; gy[head] = gyDps; mag[head] = m;
        head = (head + 1) % W; if (count < W) ++count; ++samples;
        // Infer when the window is full and then every STRIDE samples (Python: range(WIN, n + 1, STRIDE)).
        if (samples < (uint32_t)W || (samples - W) % BANDW_MODEL_STRIDE) return 0;
        float f[F]; features(f); infer(f);
        int best = 0; for (int k = 1; k < K; ++k) if (prob[k] > prob[best]) best = k;
        bool sure = best != 0 && prob[best] >= BANDW_MODEL_THRESHOLD;
        agree = sure ? (best == last ? agree + 1 : 1) : 0;
        last = sure ? best : 0;
        if (agree >= BANDW_MODEL_AGREE && samples >= coolUntil) {
            coolUntil = samples + 32;   // 0.65 s at 50 Hz, like COOLDOWN_S in the Python pipeline
            agree = 0; last = 0;
            return best;
        }
        return 0;
    }
};
